output_text:
[
  {
    "id": "obtain_cart_by_event",
    "text": "A shopper must obtain a cart before completing the trip, defined by the cart-possession transition rather than by a fixed cart-bay coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartAcquired": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cartAcquired"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper must not leave the store without the cart, expressed only through cart possession at exit so it generalizes when exits move.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper must not have a cart inside a single-file shelf aisle, using aisle geometry rather than the observed aisle coordinates.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "singleFilePassage"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_single_file_aisle",
    "text": "A shopper must not move a cart into a single-file shelf aisle, capturing the hidden distinction between cart-accessible and cart-inaccessible aisles regardless of orientation.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "singleFilePassage"
          ]
        }
      },
      "events": {
        "enteringSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enteringSingleFileShelfAisleWithCart"
    }
  },
  {
    "id": "leave_cart_only_in_open_apron",
    "text": "A shopper may leave or park a cart only in an unobstructed non-shelf area, so the rule follows functional staging spaces instead of particular parking coordinates.",
    "abstraction": {
      "state_properties": {
        "openCartStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartReleased": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartReleased",
          {
            "not": "openCartStagingArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_released_cart",
    "text": "After deliberately leaving a cart, a shopper must retrieve a cart before finishing, stated as possession-change events so it is independent of where the cart was parked.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartReleased": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartAcquired": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartReleased",
      "discharge": "cartAcquired"
    }
  },
  {
    "id": "return_to_cart_after_cartless_single_file_pick",
    "text": "After picking an item while cart-free in a single-file shelf aisle, a shopper must return to a cart, linking the obligation to the aisle-access constraint rather than to a product coordinate.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "singleFilePassage"
          ]
        }
      },
      "events": {
        "cartlessSingleFileShelfInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        },
        "cartAcquired": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFileShelfInteraction",
      "discharge": "cartAcquired"
    }
  },
  {
    "id": "use_cart_at_cart_accessible_shelf",
    "text": "When interacting with a shelf from a cart-accessible aisle, a shopper should keep the cart with them, distinguishing accessible shelf fronts from single-file aisles without relying on layout-specific locations.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "singleFilePassage"
          ]
        },
        "cartAccessibleShelfPosition": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfPosition",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
